// Host-side test for imaging/video_thumb.cpp (built into the desktop engine's CMake as `video_thumb_test`; needs
// FFmpeg, see ffmpeg_deps.cmake). `./video_thumb_test <fixtures dir>` (CMake passes it), or `bench <file>` for timings.
//
// The fixtures (imaging/test/fixtures, regenerated by make_fixtures.sh) are tiny videos that all show four flat
// quadrants -- top-left red, top-right green, bottom-left blue, bottom-right yellow -- so a wrong rotation, colour
// matrix, frame or aspect ratio shows up as a wrong colour or size:
//   - every container / codec this build decodes (MP4 H.264 + HEVC, WebM VP9, MKV, AVI MPEG-4, MPEG-PS, MPEG-TS)
//   - the three rotations phones record, and a non-square pixel aspect ratio
//   - frame selection: the first frame, a frame at a position, an explicit time, and 'hybrid' recovering from a
//     black start (the case the blank-frame retry exists for), with the duration it reports
//   - what must NOT be handled: AV1 (not compiled in), audio only, garbage, truncated and unreadable sources
//   - many threads at once (run under ASan / TSan)
#include "imaging/video_thumb.h"

#include <algorithm>
#include <atomic>
#include <chrono>
#include <cmath>
#include <csetjmp>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <fstream>
#include <iterator>
#include <string>
#include <thread>
#include <vector>

#include <jpeglib.h>  // after <cstdio>: it needs FILE

#define CHECK(cond) do { \
    if (!(cond)) { \
        std::fprintf(stderr, "CHECK FAILED at %s:%d: %s\n", __FILE__, __LINE__, #cond); \
        std::abort(); \
    } \
} while (0)

using namespace veimg;

namespace {

std::string g_dir;

std::vector<uint8_t> readFile(const std::string& name) {
    std::ifstream in(g_dir + "/" + name, std::ios::binary);
    CHECK(in.good());
    return std::vector<uint8_t>((std::istreambuf_iterator<char>(in)), std::istreambuf_iterator<char>());
}

struct Rgb {
    int r, g, b;
};
const Rgb kRed{255, 0, 0}, kGreen{0, 255, 0}, kBlue{0, 0, 255}, kYellow{255, 255, 0};

struct JErr {
    jpeg_error_mgr pub;
    std::jmp_buf jb;
};
void jErrExit(j_common_ptr c) { std::longjmp(reinterpret_cast<JErr*>(c->err)->jb, 1); }

struct Decoded {
    int w = 0, h = 0;
    std::vector<uint8_t> px;  // RGB
};

Decoded decodeJpeg(const std::vector<uint8_t>& jpg) {
    Decoded d;
    jpeg_decompress_struct ci;
    JErr err;
    std::memset(&ci, 0, sizeof(ci));
    ci.err = jpeg_std_error(&err.pub);
    err.pub.error_exit = jErrExit;
    CHECK(!setjmp(err.jb));
    jpeg_create_decompress(&ci);
    jpeg_mem_src(&ci, jpg.data(), jpg.size());
    CHECK(jpeg_read_header(&ci, TRUE) == JPEG_HEADER_OK);
    ci.out_color_space = JCS_RGB;
    jpeg_start_decompress(&ci);
    d.w = static_cast<int>(ci.output_width);
    d.h = static_cast<int>(ci.output_height);
    d.px.resize(static_cast<size_t>(d.w) * d.h * 3);
    while (ci.output_scanline < ci.output_height) {
        JSAMPROW rp = &d.px[static_cast<size_t>(ci.output_scanline) * d.w * 3];
        jpeg_read_scanlines(&ci, &rp, 1);
    }
    jpeg_finish_decompress(&ci);
    jpeg_destroy_decompress(&ci);
    return d;
}

// Video encoders round, and the quadrant edges blur: a generous tolerance still tells red from green from blue.
bool near(const uint8_t* p, const Rgb& c, int tol = 45) {
    return std::abs(p[0] - c.r) <= tol && std::abs(p[1] - c.g) <= tol && std::abs(p[2] - c.b) <= tol;
}

const uint8_t* quadrant(const Decoded& d, int qx, int qy) {
    const int x = d.w / 4 + qx * (d.w / 2), y = d.h / 4 + qy * (d.h / 2);
    return &d.px[(static_cast<size_t>(y) * d.w + x) * 3];
}

void expectQuadrants(const Decoded& d, const Rgb& tl, const Rgb& tr, const Rgb& bl, const Rgb& br) {
    CHECK(near(quadrant(d, 0, 0), tl));
    CHECK(near(quadrant(d, 1, 0), tr));
    CHECK(near(quadrant(d, 0, 1), bl));
    CHECK(near(quadrant(d, 1, 1), br));
}

VideoThumbnail run(const std::vector<uint8_t>& data, VideoOptions opt, Status expect = Status::kOk) {
    MemorySource src(data.data(), data.size());
    VideoThumbnail v;
    const Status st = makeVideoThumbnail(src, opt, v);
    if (st != expect) std::fprintf(stderr, "status %d, expected %d\n", static_cast<int>(st), static_cast<int>(expect));
    CHECK(st == expect);
    return v;
}

VideoOptions first(int target = 180) {
    VideoOptions o;
    o.targetSize = target;
    o.strategy = VideoStrategy::kFirstFrame;
    return o;
}

int g_groups = 0;
#define SECTION(name) std::printf("  %s\n", name)

void testHelpers() {
    SECTION("frame-selection helpers");
    CHECK(clampThumbnailFraction(0.0) == 0.05);
    CHECK(clampThumbnailFraction(0.5) == 0.5);
    CHECK(clampThumbnailFraction(7.0) == 0.90);
    CHECK(clampThumbnailFraction(std::nan("")) == 0.12);
    CHECK((blankFrameRetryFractions(0.12) == std::vector<double>{0.12, 0.25, 0.45}));
    CHECK((blankFrameRetryFractions(0.25) == std::vector<double>{0.25, 0.45}));
    CHECK((blankFrameRetryFractions(0.9) == std::vector<double>{0.9, 0.25, 0.45}));
    CHECK(timeAtFraction(10'000'000, 0.12) == 1'200'000);
    CHECK(timeAtFraction(10'000'000, 0.0) == 500'000);
    g_groups += 4;
}

void testContainers() {
    SECTION("containers and codecs: size, colours, duration");
    CHECK(videoThumbnailsAvailable());
    for (const char* name : {"h264.mp4", "hevc.mp4", "webm_vp9.webm", "h264.mkv", "mpeg4.avi", "mpeg2.mpg", "h264.ts"}) {
        const auto data = readFile(name);
        for (int target : {180, 64}) {
            const VideoThumbnail v = run(data, first(target));
            CHECK(!v.thumb.isPng && v.thumb.bytes.size() > 100);
            CHECK(v.thumb.sourceWidth == 160 && v.thumb.sourceHeight == 90);
            CHECK(v.thumb.width == std::min(160, target) && v.thumb.height == (target == 64 ? 36 : 90));
            CHECK(!v.thumb.isBlank);
            const Decoded d = decodeJpeg(v.thumb.bytes);
            CHECK(d.w == v.thumb.width && d.h == v.thumb.height);
            expectQuadrants(d, kRed, kGreen, kBlue, kYellow);
        }
        const VideoThumbnail v = run(data, first());
        if (std::string(name) != "h264.ts") CHECK(v.durationUs > 2'500'000 && v.durationUs < 3'500'000);
        ++g_groups;
    }
}

void testRotation() {
    SECTION("rotation recorded in the container, and pixel aspect ratio");
    struct Case { const char* file; Rgb tl, tr, bl, br; bool portrait; };
    const Case cases[] = {
        {"rot90.mp4", kGreen, kYellow, kRed, kBlue, true},    // 90 CCW
        {"rot270.mp4", kBlue, kRed, kYellow, kGreen, true},   // 90 CW
        {"rot180.mp4", kYellow, kBlue, kGreen, kRed, false},
    };
    for (const Case& c : cases) {
        const VideoThumbnail v = run(readFile(c.file), first(100));
        const Decoded d = decodeJpeg(v.thumb.bytes);
        if (c.portrait) {
            CHECK(v.thumb.sourceWidth == 90 && v.thumb.sourceHeight == 160);
            CHECK(d.w == 56 && d.h == 100);
        } else {
            CHECK(v.thumb.sourceWidth == 160 && v.thumb.sourceHeight == 90);
            CHECK(d.w == 100 && d.h == 56);
        }
        expectQuadrants(d, c.tl, c.tr, c.bl, c.br);
        ++g_groups;
    }
    // Pixel aspect 2:1: 160x90 stored, shown 320x90.
    const VideoThumbnail s = run(readFile("sar2.mp4"), first(180));
    CHECK(s.thumb.sourceWidth == 320 && s.thumb.sourceHeight == 90);
    CHECK(s.thumb.width == 180 && s.thumb.height == 51);
    expectQuadrants(decodeJpeg(s.thumb.bytes), kRed, kGreen, kBlue, kYellow);
    ++g_groups;
}

void testSelection() {
    SECTION("frame selection: first, position, explicit time, hybrid after a black start");
    const auto black = readFile("black_start.mp4");  // 1.5 s black, then 3 s of quadrants
    const VideoThumbnail f = run(black, first());
    CHECK(f.thumb.isBlank);
    CHECK(f.durationUs > 4'200'000 && f.durationUs < 4'800'000);

    VideoOptions pos;
    pos.strategy = VideoStrategy::kFrameAtPercentage;
    pos.framePosition = 0.12;  // 0.5 s: still black
    CHECK(run(black, pos).thumb.isBlank);
    pos.framePosition = 0.8;   // 3.6 s: the picture
    const VideoThumbnail p = run(black, pos);
    CHECK(!p.thumb.isBlank);
    expectQuadrants(decodeJpeg(p.thumb.bytes), kRed, kGreen, kBlue, kYellow);

    VideoOptions hybrid;  // start is black -> retries 12% (black), 25% (black), 45% (2.1 s: the picture)
    const VideoThumbnail h = run(black, hybrid);
    CHECK(!h.thumb.isBlank);
    expectQuadrants(decodeJpeg(h.thumb.bytes), kRed, kGreen, kBlue, kYellow);

    VideoOptions explicitAt;
    explicitAt.explicitTimeUs = 3'000'000;
    CHECK(!run(black, explicitAt).thumb.isBlank);
    explicitAt.explicitTimeUs = 0;
    CHECK(run(black, explicitAt).thumb.isBlank);  // explicit means exactly that: no retry
    explicitAt.explicitTimeUs = 600'000'000;      // far past the end: the last keyframe, not an error
    CHECK(!run(black, explicitAt).thumb.isBlank);

    // A video that does not start blank is left alone by 'hybrid'.
    const VideoThumbnail plain = run(readFile("h264.mp4"), hybrid);
    CHECK(!plain.thumb.isBlank);
    g_groups += 3;
}

void testUnsupported() {
    SECTION("what this build must not claim");
    run(readFile("av1.mp4"), first(), Status::kUnsupported);        // decoder not compiled in: use another route
    run(readFile("audio_only.m4a"), first(), Status::kFailed);      // no video stream
    std::vector<uint8_t> garbage(8000);
    for (size_t i = 0; i < garbage.size(); ++i) garbage[i] = static_cast<uint8_t>(i * 37 + 11);
    run(garbage, first(), Status::kUnsupported);
    run({}, first(), Status::kUnsupported);

    // Truncated: never a crash, never a wrong claim of success without a picture.
    for (const char* name : {"h264.mp4", "h264.mkv", "h264.ts", "mpeg4.avi", "webm_vp9.webm"}) {
        const auto full = readFile(name);
        for (size_t cut : {full.size() / 10, full.size() / 2, full.size() * 9 / 10}) {
            const std::vector<uint8_t> part(full.begin(), full.begin() + static_cast<long>(cut));
            MemorySource src(part.data(), part.size());
            VideoThumbnail v;
            const Status st = makeVideoThumbnail(src, first(), v);
            CHECK(st == Status::kOk || st == Status::kFailed || st == Status::kUnsupported);
            if (st == Status::kOk) CHECK(!v.thumb.bytes.empty());
        }
    }

    // Unreadable sources.
    struct Failing : ByteSource {
        const std::vector<uint8_t>& d;
        int64_t failAfter;
        Failing(const std::vector<uint8_t>& data, int64_t after) : d(data), failAfter(after) {}
        int64_t size() override { return static_cast<int64_t>(d.size()); }
        int64_t readAt(int64_t off, uint8_t* dst, size_t len) override {
            if (off >= failAfter) return -1;
            if (static_cast<size_t>(off) >= d.size()) return 0;
            const size_t n = std::min({len, d.size() - static_cast<size_t>(off), static_cast<size_t>(failAfter - off)});
            std::memcpy(dst, d.data() + off, n);
            return static_cast<int64_t>(n);
        }
    };
    const auto mp4 = readFile("h264.mp4");
    Failing never(mp4, 0);
    VideoThumbnail v;
    CHECK(makeVideoThumbnail(never, first(), v) == Status::kIoError);
    Failing midway(mp4, static_cast<int64_t>(mp4.size() / 2));
    const Status st = makeVideoThumbnail(midway, first(), v);
    CHECK(st == Status::kIoError || st == Status::kFailed || st == Status::kUnsupported);
    g_groups += 4;
}

void testThreads() {
    SECTION("many threads at once");
    const std::vector<std::vector<uint8_t>> files = {readFile("h264.mp4"), readFile("hevc.mp4"), readFile("webm_vp9.webm"),
                                                     readFile("h264.mkv"), readFile("mpeg4.avi"), readFile("black_start.mp4")};
    std::atomic<int> bad{0};
    std::vector<std::thread> pool;
    for (int t = 0; t < 6; ++t) {
        pool.emplace_back([&, t] {
            for (int i = 0; i < 12; ++i) {
                const auto& f = files[(t + i) % files.size()];
                MemorySource src(f.data(), f.size());
                VideoOptions opt;  // hybrid: also exercises seeking
                VideoThumbnail v;
                if (makeVideoThumbnail(src, opt, v) != Status::kOk || v.thumb.isBlank) ++bad;
            }
        });
    }
    for (auto& t : pool) t.join();
    CHECK(bad == 0);
    ++g_groups;
}

void bench(const std::string& path) {
    std::ifstream in(path, std::ios::binary);
    CHECK(in.good());
    const std::vector<uint8_t> data((std::istreambuf_iterator<char>(in)), std::istreambuf_iterator<char>());
    MemorySource src(data.data(), data.size());
    for (VideoStrategy s : {VideoStrategy::kFirstFrame, VideoStrategy::kFrameAtPercentage, VideoStrategy::kHybrid}) {
        VideoOptions opt;
        opt.strategy = s;
        VideoThumbnail v;
        makeVideoThumbnail(src, opt, v);  // warm up
        const int reps = 10;
        const auto t0 = std::chrono::steady_clock::now();
        Status st = Status::kOk;
        for (int i = 0; i < reps; ++i) st = makeVideoThumbnail(src, opt, v);
        const double ms = std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - t0).count() / reps;
        std::printf("  strategy %d: status %d, %.1f ms per thumbnail, %dx%d from %dx%d, %zu bytes\n", static_cast<int>(s),
                    static_cast<int>(st), ms, v.thumb.width, v.thumb.height, v.thumb.sourceWidth, v.thumb.sourceHeight,
                    v.thumb.bytes.size());
    }
}

}  // namespace

int main(int argc, char** argv) {
    if (argc > 2 && std::string(argv[1]) == "bench") {
        bench(argv[2]);
        return 0;
    }
    g_dir = argc > 1 ? argv[1] : "imaging/test/fixtures";
    std::printf("video_thumb_test\n");
    testHelpers();
    testContainers();
    testRotation();
    testSelection();
    testUnsupported();
    testThreads();
    std::printf("%d groups of checks passed\n", g_groups);
    return 0;
}
